	@Test
	public void retainedRootStepObservesOneNowPerEvaluationAndAFreshNowEachEvaluation() throws Exception {
		String query = "SELECT ?s WHERE { ?s <" + EX + "link> ?o . FILTER(<" + RECORD_NOW_URI + ">(NOW())) }";
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(root,
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, (NativeLmdbQuerySource) dataset);
		assertThat(outcome.isSupported())
				.as("the pattern+filter root must compile natively with a generic filter bridge "
						+ "(precondition for this scope test)")
				.isTrue();
		QueryEvaluationStep step = outcome.step();

		List<Value> firstEvaluation = drainAndCollectNow(step);
		Thread.sleep(25);
		List<Value> secondEvaluation = drainAndCollectNow(step);

		assertThat(firstEvaluation).as("the filter must have run at least once per evaluation").isNotEmpty();
		assertThat(secondEvaluation).isNotEmpty();
		assertThat(new HashSet<>(firstEvaluation))
				.as("all rows of one evaluation must observe one NOW value")
				.hasSize(1);
		assertThat(new HashSet<>(secondEvaluation))
				.as("all rows of one evaluation must observe one NOW value")
				.hasSize(1);
		assertThat(secondEvaluation.get(0))
				.as("a new evaluation of a retained compiled step must observe a fresh NOW value")
				.isNotEqualTo(firstEvaluation.get(0));
	}

